    CONSTRAINT check_interest_config CHECK (((interest_enabled = false) OR ((interest_enabled = true) AND (interest_type IS NOT NULL) AND (interest_rate IS NOT NULL) AND (interest_period IS NOT NULL)))),
    CONSTRAINT check_principal_positive CHECK ((principal_amount > (0)::numeric)),
