--
-- Name: transaction_mappings; Type: TABLE; Schema: public; Owner: plumo
--

CREATE TABLE public.transaction_mappings (
    id integer NOT NULL,
    mapping_type character varying(20) DEFAULT 'exact'::character varying NOT NULL,
    original_description text,
    pattern text,
    regex_pattern text,
    mapped_description text,
    priority integer DEFAULT 1 NOT NULL,
    subtag_id integer NOT NULL,
    is_sensitive boolean DEFAULT false NOT NULL,
    expense_sharing_id integer,
    my_contribution_percentage numeric(5,2),
    revenue_contribution_percentage numeric(5,2),
    account_id integer NOT NULL,
    tenant_id integer NOT NULL,
    created_by integer NOT NULL,
    created_at timestamp without time zone DEFAULT now(),
    last_updated_at timestamp without time zone DEFAULT now(),
    CONSTRAINT check_contribution_percentage CHECK (((my_contribution_percentage IS NULL) OR ((my_contribution_percentage >= (0)::numeric) AND (my_contribution_percentage <= (100)::numeric)))),
    CONSTRAINT check_mapping_type CHECK (((mapping_type)::text = ANY (ARRAY[('exact'::character varying)::text, ('pattern'::character varying)::text, ('regex'::character varying)::text]))),
    CONSTRAINT check_priority CHECK (((priority >= 0) AND (priority <= 2))),
    CONSTRAINT check_revenue_contribution_percentage CHECK (((revenue_contribution_percentage IS NULL) OR ((revenue_contribution_percentage >= (0)::numeric) AND (revenue_contribution_percentage <= (100)::numeric))))
);


ALTER TABLE public.transaction_mappings OWNER TO plumo;

--
-- Name: TABLE transaction_mappings; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON TABLE public.transaction_mappings IS 'Mapeamentos de transações para categorização automática. Suporta exact match, pattern matching e regex. Todas as buscas são case-insensitive.';


--
-- Name: COLUMN transaction_mappings.mapping_type; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.mapping_type IS 'Tipo de mapeamento: exact (descrição completa), pattern (contém texto), regex (expressão regular)';


--
-- Name: COLUMN transaction_mappings.original_description; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.original_description IS 'Descrição original da transação (sempre em lowercase). Usado apenas para mapping_type=exact.';


--
-- Name: COLUMN transaction_mappings.pattern; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.pattern IS 'Texto a buscar dentro da descrição (para mapping_type=pattern). Busca case-insensitive.';


--
-- Name: COLUMN transaction_mappings.regex_pattern; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.regex_pattern IS 'Expressão regular para matching avançado (para mapping_type=regex). Busca case-insensitive.';


--
-- Name: COLUMN transaction_mappings.mapped_description; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.mapped_description IS 'Descrição personalizada/ofuscada. Se is_sensitive=TRUE, este campo é criptografado.';


--
-- Name: COLUMN transaction_mappings.priority; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.priority IS 'Prioridade do mapeamento: 0=Alta, 1=Média, 2=Baixa. Menor valor = testado primeiro. Usado para desempate quando múltiplos mapeamentos correspondem';


--
-- Name: COLUMN transaction_mappings.is_sensitive; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.is_sensitive IS 'Se TRUE, mapped_description é criptografado no banco e ofuscado na interface (ex: apps de namoro, sites adultos)';


--
-- Name: COLUMN transaction_mappings.expense_sharing_id; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.expense_sharing_id IS 'FK para expense_sharing_settings. Define configuração de compartilhamento padrão para despesas com esta descrição.';


--
-- Name: COLUMN transaction_mappings.my_contribution_percentage; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.my_contribution_percentage IS 'Override do % de DESPESA neste mapeamento (0-100). Se NULL, usa cartão/config.';


--
-- Name: COLUMN transaction_mappings.revenue_contribution_percentage; Type: COMMENT; Schema: public; Owner: plumo
--

COMMENT ON COLUMN public.transaction_mappings.revenue_contribution_percentage IS 'Override do % de RECEITA neste mapeamento (0-100). Se NULL, usa cartão/config.';


