CREATE TABLE public.users_sessions (
    id integer NOT NULL,
    token_hash character varying(255) NOT NULL,
    expires_at timestamp without time zone NOT NULL,
    ip_address character varying(45),
    user_agent text,
    user_id integer NOT NULL,
    tenant_id integer NOT NULL,
    created_by integer,
    created_at timestamp without time zone DEFAULT now(),
    last_updated_at timestamp without time zone DEFAULT now(),
    active boolean DEFAULT true NOT NULL
);


ALTER TABLE public.users_sessions OWNER TO plumo;

--
-- Name: users_sessions_id_seq; Type: SEQUENCE; Schema: public; Owner: plumo
--

CREATE SEQUENCE public.users_sessions_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.users_sessions_id_seq OWNER TO plumo;

--
-- Name: users_sessions_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: plumo
--

ALTER SEQUENCE public.users_sessions_id_seq OWNED BY public.users_sessions.id;


